```javascript
// 1. 一次提交多个搜索词，每个词各取前 3 条候选
const groups = await eda.lib_Device.batchSearchDevices({
  queries: [
    { wd: '10k 0402', limit: 3 },
    { wd: '100nF 0603', limit: 3 },
  ],
});

// 2. 按搜索词读取命中结果（symbol / footprint 不可用时为 null）
groups.forEach(group => {
  console.log('搜索词:', group.wd, '命中总数:', group.total);
  group.devices.forEach(device => {
    console.log('  uuid:', device.uuid, '标题:', device.displayTitle);
    console.log('  符号:', device.symbol ? device.symbol.displayTitle : null);
    console.log('  封装:', device.footprint ? device.footprint.displayTitle : null);
  });
});

// 3. 某个词需要更多候选时分页取下一页
const nextPageGroups = await eda.lib_Device.batchSearchDevices({
  queries: [{ wd: '10k 0402', limit: 3, offset: 3 }],
});
console.log('第二页条数:', nextPageGroups[0]?.devices.length ?? 0);
```
